{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Cohort-style wellness coaching that helps you build simple, sustainable habits and frameworks to reach daily goals." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="split-diagonal">
  <header class="site-header">
    <div class="container">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="/about.html">Why Join</a>
        <a href="/programs.html">Programs</a>
        <a href="/services.html">Sessions</a>
        <a href="/pricing.html">Investment</a>
        <a href="/testimonials.html">Stories</a>
        <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
        <a href="/contact.html" class="muted">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO (left diagonal) -->
    <section class="hero layer-left" data-reveal>
      <div class="container hero-inner">
        <div class="hero-copy">
          <h1>Gentle shifts. Measurable habits.</h1>
          <p class="lead">Join a guided cohort that turns small daily moves into steady gains — no strict rules, just clear frameworks that stick.</p>
          <p class="meta">Starts next cohort: <strong>6 weeks</strong> &middot; Live weekly check-ins &middot; Group momentum</p>
          <div class="hero-ctas">
            <a href="{{PRIMARY_CTA_URL}}" class="btn primary">{{PRIMARY_CTA_LABEL}}</a>
            <a href="/programs.html" class="btn ghost">See cohorts & pricing</a>
          </div>
        </div>
        <div class="hero-card" aria-hidden="true">
          <svg class="pattern" width="280" height="420" viewBox="0 0 280 420" xmlns="http://www.w3.org/2000/svg" role="img" aria-hidden="true">
            <defs>
              <pattern id="p1" patternUnits="userSpaceOnUse" width="40" height="40">
                <rect width="40" height="40" fill="#f6f7fb" />
                <path d="M0 20 L20 0 M20 40 L40 20" stroke="#e6eef9" stroke-width="2"/>
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#p1)"/>
          </svg>
          <div class="card-content">
            <h3>Next cohort snapshot</h3>
            <ul>
              <li>Weekly live practice labs</li>
              <li>Short daily prompts</li>
              <li>One 1:1 planning session</li>
            </ul>
            <a href="/book.html" class="btn small">Reserve a seat</a>
          </div>
        </div>
      </div>
    </section>

    <!-- WHAT TO EXPECT (with Session Planner widget) -->
    <section class="what-to-expect" data-reveal>
      <div class="container">
        <h2>What you'll leave the cohort with</h2>
        <p class="sub">Frameworks you can actually use, habits that fit your life, and clear next steps to keep momentum beyond the program.</p>

        <div class="expect-grid">
          <article class="card">
            <h3>Outcome-driven focuses</h3>
            <p>We map 2–3 measurable targets so each week builds toward a usable outcome.</p>
          </article>
          <article class="card">
            <h3>Micro-habits that stack</h3>
            <p>Daily mini-practices designed to fit short schedules and compound over time.</p>
          </article>
          <article class="card">
            <h3>Repeatable routines</h3>
            <p>Simple templates for mornings, evenings, and midday resets to anchor energy.</p>
          </article>
        </div>

        <div class="planner" id="session-planner">
          <h3>Session Planner — Draft your cohort plan</h3>
          <p class="muted">Build a short, exportable plan you can bring to your first session.</p>

          <form id="planner-form">
            <label>Full name<input type="text" name="name" placeholder="Your name"></label>
            <label>Primary goal<textarea name="goal" rows="2" placeholder="What do you want to improve in 6 weeks?"></textarea></label>
            <div class="row">
              <label>Days per week
                <select name="days">
                  <option>1</option>
                  <option>2</option>
                  <option selected>3</option>
                  <option>4</option>
                  <option>5</option>
                </select>
              </label>
              <label>Minutes per day
                <select name="minutes">
                  <option>5</option>
                  <option selected>10</option>
                  <option>15</option>
                  <option>20</option>
                </select>
              </label>
            </div>

            <fieldset class="focus-areas">
              <legend>Focus areas (pick up to 3)</legend>
              <label><input type="checkbox" name="focus" value="Movement"> Movement</label>
              <label><input type="checkbox" name="focus" value="Sleep"> Sleep</label>
              <label><input type="checkbox" name="focus" value="Nutrition"> Nutrition</label>
              <label><input type="checkbox" name="focus" value="Stress"> Stress & calm</label>
              <label><input type="checkbox" name="focus" value="Routines"> Daily routines</label>
            </fieldset>

            <label>Barriers<textarea name="barriers" rows="2" placeholder="What's in the way? (time, travel, energy, etc.)"></textarea></label>

            <div class="planner-actions">
              <button type="button" id="build-plan" class="btn primary">Build my plan</button>
              <button type="button" id="copy-plan" class="btn ghost" disabled>Copy text</button>
              <button type="button" id="download-plan" class="btn ghost" disabled>Download .txt</button>
            </div>
          </form>

          <pre id="plan-output" aria-live="polite">Your plan will appear here after you click "Build my plan".</pre>
        </div>

      </div>
    </section>

    <!-- GALLERY (visuals and cohort highlights) -->
    <section class="gallery" data-reveal>
      <div class="container">
        <h2>Snapshots from past cohorts</h2>
        <p class="sub">Real participants, actionable shifts. Short prompts, big changes over weeks.</p>
        <div class="grid">
          <figure class="tile" aria-hidden>
            <svg viewBox="0 0 400 280" preserveAspectRatio="xMidYMid slice"><rect width="100%" height="100%" fill="#fff6f3"/><text x="20" y="50" font-size="18" fill="#d95c5c">Group exercise</text></svg>
            <figcaption>Live lab on habit design</figcaption>
          </figure>
          <figure class="tile" aria-hidden>
            <svg viewBox="0 0 400 280" preserveAspectRatio="xMidYMid slice"><rect width="100%" height="100%" fill="#f3f8ff"/><text x="20" y="50" font-size="18" fill="#4366b2">Micro-practices</text></svg>
            <figcaption>Quick daily prompts</figcaption>
          </figure>
          <figure class="tile" aria-hidden>
            <svg viewBox="0 0 400 280" preserveAspectRatio="xMidYMid slice"><rect width="100%" height="100%" fill="#f9fff2"/><text x="20" y="50" font-size="18" fill="#5b8b42">Progress check</text></svg>
            <figcaption>Weekly check-ins</figcaption>
          </figure>
        </div>
      </div>
    </section>

    <!-- OBJECTIONS -->
    <section class="objections" data-reveal>
      <div class="container">
        <h2>Questions people ask</h2>
        <div class="faq">
          <details>
            <summary>What if I don't have time?</summary>
            <p>We design tiny, repeatable practices that take minutes. The cohort teaches how to fit them into days so they stick.</p>
          </details>
          <details>
            <summary>Is this medical advice?</summary>
            <p>No. This is coaching focused on habits, routines and frameworks — not diagnoses or medical treatment.</p>
          </details>
          <details>
            <summary>Will I get one-on-one attention?</summary>
            <p>Cohorts include a 1:1 planning session to tailor your roadmap plus small-group check-ins for accountability.</p>
          </details>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta" data-reveal>
      <div class="container">
        <h2>Ready to join the next cohort in {{CITY}}, {{STATE}}?</h2>
        <p>Reserve your spot or request a call — seats fill as groups form.</p>
        <div class="cta-row">
          <a href="{{PRIMARY_CTA_URL}}" class="btn primary large">{{PRIMARY_CTA_LABEL}}</a>
          <a href="/contact.html" class="btn ghost large">Ask a question</a>
        </div>
        <p class="contact">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container">
      <p>&copy; <span id="yr"></span> {{BUSINESS_NAME}} — Cohort-style wellness coaching. All rights reserved.</p>
      <nav class="small-nav">
        <a href="/about.html">About</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/contact.html">Contact</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
