{"path":"assets/css/styles.css","content":"/* Base styles */
:root{
  --bg:#ffffff;
  --muted:#6b7280;
  --accent:#5b9bd5;
  --accent-2:#f28b6b;
  --dark:#0f1724;
  --card:#ffffff;
  --glass:rgba(255,255,255,0.7);
  --radius:12px;
  font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:linear-gradient(180deg,#fbfcff 0%,#ffffff 100%);color:var(--dark);-webkit-font-smoothing:antialiased}
.container{max-width:1100px;margin:0 auto;padding:28px}
.site-header{position:sticky;top:0;background:rgba(255,255,255,0.6);backdrop-filter:blur(6px);z-index:30;border-bottom:1px solid rgba(16,24,40,0.04)}
.site-header .container{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--dark);text-decoration:none}
.main-nav a{margin-left:14px;color:var(--dark);text-decoration:none}
.main-nav .cta{background:var(--accent);color:white;padding:8px 12px;border-radius:8px}
.main-nav .muted{color:var(--muted)}
.split-diagonal main{position:relative}
/* hero */
.hero{display:flex;align-items:stretch;padding:48px 0}
.hero-inner{display:flex;gap:28px;align-items:stretch}
.hero-copy{flex:1}
.hero h1{font-size:34px;margin:0 0 12px}
.hero .lead{color:var(--muted);margin:0 0 8px}
.hero .meta{font-size:13px;color:var(--muted)}
.hero-ctas{margin-top:18px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;border:1px solid transparent;font-weight:600}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;color:var(--accent);border-color:rgba(91,155,213,0.12)}
.btn.small{padding:8px 10px;font-size:13px}
.btn.large{padding:14px 18px;font-size:16px}
.hero-card{width:320px;background:linear-gradient(180deg,#fff,#fafcff);border-radius:14px;padding:16px;box-shadow:0 6px 18px rgba(15,23,36,0.06);display:flex;flex-direction:column;align-items:flex-start}
.pattern{position:absolute;left:-40px;top:-60px;opacity:0.9}
.card-content h3{margin-top:0}
/* diagonal split look */
.split-diagonal::before{content:'';position:absolute;left:0;right:0;top:0;height:60vh;background:linear-gradient(135deg,#f7fbff 0%,#ffffff 100%);transform:skewY(-3deg);transform-origin:0;pointer-events:none}
/* sections */
section{padding:48px 0}
.what-to-expect .expect-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
.card{background:var(--card);border-radius:10px;padding:18px;box-shadow:0 4px 12px rgba(15,23,36,0.04)}
.planner{margin-top:22px;background:linear-gradient(180deg,#ffffff,#fbfcff);padding:18px;border-radius:10px}
.planner form{display:grid;gap:10px}
.planner label{display:block;font-size:14px}
.planner input[type="text"],.planner textarea,.planner select{width:100%;padding:8px;border-radius:8px;border:1px solid #e6eef9;background:transparent}
.row{display:flex;gap:10px}
.row label{flex:1}
.focus-areas{display:flex;gap:10px;flex-wrap:wrap;padding:8px 0;border:none}
.focus-areas label{font-size:14px}
.planner-actions{display:flex;gap:8px;margin-top:8px}
#plan-output{white-space:pre-wrap;background:#f8f9ff;padding:12px;border-radius:10px;border:1px dashed rgba(16,24,40,0.06);min-height:110px}
/* gallery */
.gallery .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}
.tile{background:#fff;border-radius:12px;padding:0;overflow:hidden;box-shadow:0 6px 18px rgba(15,23,36,0.04)}
.tile figcaption{padding:10px;font-size:13px;color:var(--muted)}
/* objections */
.faq details{background:var(--card);padding:12px;border-radius:10px;margin-bottom:8px}
.faq summary{font-weight:600;cursor:pointer}
/* final CTA */
.final-cta{text-align:center;background:linear-gradient(180deg,#f7fbff,#ffffff);border-radius:12px}
.cta-row{display:flex;gap:12px;justify-content:center;margin-top:14px}
.site-footer{padding:24px 0;color:var(--muted);border-top:1px solid rgba(16,24,40,0.04)}
.small-nav a{margin-left:10px;color:var(--muted);text-decoration:none}
/* reveal animation */
[data-reveal]{opacity:0;transform:translateY(18px);transition:opacity 420ms cubic-bezier(.2,.9,.3,1),transform 420ms cubic-bezier(.2,.9,.3,1)}
[data-reveal].revealed{opacity:1;transform:none}
/* Reduced motion */
@media (prefers-reduced-motion: reduce){
  [data-reveal]{transition:none!important;opacity:1;transform:none}
}
/* responsiveness */
@media (max-width:900px){
  .hero-inner{flex-direction:column}
  .hero-card{width:100%}
  .what-to-expect .expect-grid{grid-template-columns:1fr}
  .gallery .grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utilities
  function qs(sel, ctx){return (ctx||document).querySelector(sel)}
  function qsa(sel, ctx){return Array.from((ctx||document).querySelectorAll(sel))}

  // Year in footer
  var yr = qs('#yr'); if(yr) yr.textContent = new Date().getFullYear();

  // Scroll-triggered reveal (with prefers-reduced-motion support)
  var prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var revealTargets = qsa('[data-reveal]');
  if(prefersReduced){ revealTargets.forEach(function(el){ el.classList.add('revealed'); }); }
  else if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){ e.target.classList.add('revealed'); io.unobserve(e.target); }
      });
    },{rootMargin:'-10% 0px',threshold:0.08});
    revealTargets.forEach(function(el){ io.observe(el); });
  } else { revealTargets.forEach(function(el){ el.classList.add('revealed'); }); }

  // Session Planner widget
  var form = qs('#planner-form');
  var buildBtn = qs('#build-plan');
  var copyBtn = qs('#copy-plan');
  var downloadBtn = qs('#download-plan');
  var output = qs('#plan-output');

  function gatherForm(){
    var data = {};
    var f = new FormData(form);
    data.name = (f.get('name')||'').trim();
    data.goal = (f.get('goal')||'').trim();
    data.days = f.get('days')||'3';
    data.minutes = f.get('minutes')||'10';
    data.barriers = (f.get('barriers')||'').trim();
    var focuses = f.getAll('focus')||[];
    data.focuses = focuses;
    return data;
  }

  function buildPlanText(d){
    var lines = [];
    lines.push('Cohort Plan — ' + (d.name || 'Participant'));
    lines.push('Primary goal: ' + (d.goal || '—'));
    lines.push('Commitment: ' + d.days + ' days/week, ' + d.minutes + ' minutes/day');
    if(d.focuses && d.focuses.length){
      lines.push('Focus areas: ' + d.focuses.join(', '));
    } else {
      lines.push('Focus areas: (none selected)');
    }
    if(d.barriers) lines.push('Anticipated barriers: ' + d.barriers);

    // Simple micro-habit suggestions (non-medical)
    lines.push('\nSuggested micro-practices:');
    if(d.focuses.indexOf('Movement')>-1) lines.push('- Movement: 7-minute mobility sequence after waking (3x/wk build to daily)');
    if(d.focuses.indexOf('Sleep')>-1) lines.push('- Sleep: 10-minute wind-down with reduced screen time + breathing cues 30m before bed');
    if(d.focuses.indexOf('Nutrition')>-1) lines.push('- Nutrition: One 200-calorie protein-rich snack between meals on training days');
    if(d.focuses.indexOf('Stress')>-1) lines.push('- Stress & calm: Two short grounding exercises (2–5 mins) during midday dips');
    if(d.focuses.indexOf('Routines')>-1) lines.push('- Routines: 3-step morning anchor to start the day consistently');

    lines.push('\nWeek-by-week plan:');
    lines.push('Week 1: orient + pick baseline micro-habit');
    lines.push('Weeks 2–4: layer practices; weekly lab to refine technique');
    lines.push('Weeks 5–6: consolidate, craft a sustainable maintenance template');

    lines.push('\nNotes: This is coaching guidance focused on habits and frameworks, not medical advice.\n');
    return lines.join('\n');
  }

  buildBtn && buildBtn.addEventListener('click', function(){
    var data = gatherForm();
    if(!data.goal){ output.textContent = 'Please add a clear primary goal to get a tailored plan.'; copyBtn.disabled=true; downloadBtn.disabled=true; return; }
    var text = buildPlanText(data);
    output.textContent = text;
    copyBtn.disabled = false; downloadBtn.disabled = false;
  });

  copyBtn && copyBtn.addEventListener('click', function(){
    var text = output.textContent || '';
    if(!text) return;
    navigator.clipboard && navigator.clipboard.writeText ? navigator.clipboard.writeText(text).then(function(){
      copyBtn.textContent = 'Copied!'; setTimeout(function(){ copyBtn.textContent='Copy text'; },1500);
    }) : (function(){
      // fallback
      var ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta); ta.select(); try{document.execCommand('copy'); copyBtn.textContent='Copied!'; setTimeout(function(){ copyBtn.textContent='Copy text'; },1500);}catch(e){} ta.remove();
    })();
  });

  downloadBtn && downloadBtn.addEventListener('click', function(){
    var text = output.textContent || '';
    if(!text) return;
    var blob = new Blob([text],{type:'text/plain'});
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a'); a.href = url; a.download = 'cohort-plan.txt'; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
  });

  // Accessible enhancements: keyboard focus visible for buttons
  document.addEventListener('keyup', function(e){ if(e.key==='Tab') document.body.classList.add('show-focus'); });
})();
"} 
